export type MeetingVectorName = keyof typeof meetingIcons;
export function meetingVector(
  name: MeetingVectorName,
  size: number | string = 20,
  color = '#ffffff',
): SettingsVectorNode {
  const resolve = (node: SettingsVectorNode): SettingsVectorNode => ({
    ...node,
    attrs: Object.fromEntries(
      Object.entries(node.attrs).map(([k, v]) => [
        k,
        v === '$svgSize' ? size : v === '$color' ? color : v,
      ]),
    ),
    children: node.children.map(resolve),
  });
  return resolve(meetingIcons[name]);
}
